-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.unpublish_log (
  id bigint generated always as identity not null,
  kind text not null,
  item_id text not null,
  title text,
  reason text not null,
  requested_by text not null,
  removed jsonb not null,
  done_at timestamp with time zone default now() not null,
  constraint unpublish_log_pkey PRIMARY KEY (id),
  constraint unpublish_log_kind_check CHECK ((kind = ANY (ARRAY['note'::text, 'deck'::text, 'quiz'::text, 'image'::text]))),
  constraint unpublish_log_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 500))),
  constraint unpublish_log_requested_by_check CHECK (((length(btrim(requested_by)) >= 1) AND (length(btrim(requested_by)) <= 200)))
);

CREATE TRIGGER unpublish_log_drops_browse_indexes AFTER INSERT ON public.unpublish_log FOR EACH ROW EXECUTE FUNCTION public.unpublish_log_drops_browse_indexes();
CREATE TRIGGER unpublish_log_to_draft AFTER INSERT ON public.unpublish_log FOR EACH ROW EXECUTE FUNCTION public.unpublish_log_to_draft();

alter table public.unpublish_log enable row level security;
